SET client_encoding = 'UTF8';

BEGIN;

-- Audit triggers are disabled only for this initial load and re-enabled at the end.
-- Only triggers that call audit_row_change() are touched; no other trigger or constraint is changed.
DO $$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT tgrelid::regclass AS table_name, tgname
          FROM pg_trigger
         WHERE tgfoid = 'audit_row_change'::regproc
           AND NOT tgisinternal
    LOOP
        EXECUTE format('ALTER TABLE %s DISABLE TRIGGER %I', t.table_name, t.tgname);
    END LOOP;
END;
$$;



















-- Document numbers were issued explicitly: move the counters to the highest number of each year.
UPDATE number_ranges SET last_value = 363
 WHERE document_type = 'purchase_order' AND fiscal_year = 2025;
