 WHERE document_type = 'purchase_requisition' AND fiscal_year = 2025;
UPDATE number_ranges SET last_value = 972
 WHERE document_type = 'purchase_requisition' AND fiscal_year = 2026;

-- Sequences continue after the explicit ids.
