DO $$
DECLARE
    t record;
BEGIN
    FOR t IN
        SELECT tgrelid::regclass AS table_name, tgname
          FROM pg_trigger
         WHERE tgfoid = 'audit_row_change'::regproc
           AND NOT tgisinternal
    LOOP
        EXECUTE format('ALTER TABLE %s ENABLE TRIGGER %I', t.table_name, t.tgname);
    END LOOP;
